    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    int num = 29;
    if (is_prime(num)) printf("%d is prime.\n", num);
    else printf("%d is not prime.\n", num);
    return 0;
}
```

